// Settings of the Raspberry Pi Pico (RP2040) benchmark firmware.
// The model and its constants are in model_data.h, generated by
// ml/convert_tflite.py (the same model as the ESP32-S3).

#pragma once

#include <Arduino.h>

// ---- I2C bus (BME280 and INA219), I2C0 of the Pico ----
// GP4 is physical pin 6 and GP5 is physical pin 7 of the board.
const int I2C_SDA_PIN = 4;
const int I2C_SCL_PIN = 5;
const uint8_t BME280_I2C_ADDRESS = 0x76;
const uint8_t INA219_I2C_ADDRESS = 0x40;

// ---- Serial port (USB of the Pico) ----
const unsigned long SERIAL_BAUD_RATE = 115200;

// ---- Totals used for the percentages (RP2040 / Pico datasheets) ----
const unsigned long PICO_FLASH_BYTES = 2UL * 1024 * 1024;  // 2 MB external flash
const unsigned long PICO_SRAM_BYTES = 264UL * 1024;        // 264 KB on-chip SRAM

// ---- TensorFlow Lite Micro ----
// Same reserved size as the ESP32-S3, so both reports are comparable.
const int TENSOR_ARENA_BYTES = 16 * 1024;

// Number of inferences timed by BENCHMARK (R7 asks for >= 100)
const int BENCHMARK_RUNS = 200;

// ---- Power measurement (INA219, optional) ----
const int POWER_SAMPLES = 50;                     // readings averaged
const unsigned long POWER_SAMPLE_PERIOD_MS = 20;  // time between readings

// Set to 1 to run the benchmark automatically a few seconds after power-on.
// Needed to measure power: then the Pico is powered through the INA219 and
// no PC is connected. Read the saved report later with LASTBENCH.
#define RUN_BENCHMARK_AT_BOOT 0
const unsigned long BENCHMARK_AT_BOOT_DELAY_MS = 10000;
const char BENCHMARK_FILE_PATH[] = "/benchmark.txt";
